# এসএসসি সাধারণ গণিত অধ্যায় ৪: সহজ–মধ্যম মানের ১০টি সমন্বিত সৃজনশীল প্রশ্ন (৪.১, ৪.২, ৪.৩ মিশিয়ে); ক (২), খ (৪), গ (৪)
# gen_cq_c10_4.py এটি import করে cq_c10_4.json এ b31 থেকে যোগ করে।
import math, sympy as sp
from sympy import Rational as R, log
x,n=sp.symbols('x n',positive=True)
L=math.log10; l2,l3,l7=0.3010,0.4771,0.8451

# ---------- যাচাই ----------
assert 150000000==1.5e8 and 300000==3e5 and 1.5e8/3e5==500 and 500==8*60+20 and round(l3-l2,4)==0.1761 and round(8+0.1761,4)==8.1761 and round(2+(1-l2),4)==2.6990 and abs(L(500)-2.6990)<1e-4
assert 2**6==64 and round((l2+l3)/l2,3)==2.585 and round(6*l2,4)==1.8060 and 64==6.4e1
assert abs(L(0.00725)-(-3+0.8603))<1e-4 and round(-3+0.8603,4)==-2.1397 and 0.00725*1e5==725 and round(-2.1397/2,5)==-1.06985 and round(-1.06985+2,4)==0.9302
assert sp.simplify(5**(n+1)-5**n-4*5**n)==0 and sp.simplify((5**(n+1)-5**n)/(4*5**(n-1)))==5 and 4*5**3==500 and 4*5**2==100
assert 3**4==81 and R(1,9)==sp.Integer(3)**-2 and 3*R(1,9)==R(1,3) and sp.simplify(log(81*R(1,9),3)+log(sp.sqrt(3),3))==R(5,2)
assert 500*2**3==4000 and 500*2**6==32000 and round((3+l2)/l2,2)==10.97 and 500*2**11>=10**6>500*2**10
assert round(2*l3+3*l2,4)==1.8572 and 3**2*2**3==72 and round(5*(l3-l2),4)==0.8805 and R(3,2)**5==R(243,32) and abs(L(243/32)-0.8805)<1e-4
assert sp.simplify(2**(x+1)*3**(x-1)/6**x)==R(2,3) and sp.solve(sp.Integer(6)**x-36,x)==[2]
assert round(l3+l7,4)==1.3222 and round(2*l2+l3+l7,4)==1.9242 and round(1.9242-4,4)==-2.0758 and abs(L(0.0084)+2.0758)<1e-4 and round((l2+l3+l7)/l7,2)==1.92 and abs(math.log(42)/math.log(7)-1.92)<1e-2
assert sp.solve(x**2-1-8,x)==[3] and log(243,3)==5 and sp.simplify(9**log(5,3))==25

